//! Line tables of real code objects compiled by CPython 3.12, 3.13 and 3.14.
//!
//! The fixtures are generated by `tests/fixtures/gen_linetables.py` from
//! `tests/fixtures/linetable_source.py`; see that script for how to
//! regenerate them. Each holds `co_linetable`, `co_firstlineno`,
//! `co_positions()` and `co_lines()` for every code object in the source.

use std::collections::BTreeSet;
use std::path::PathBuf;

use heapspy_alloc::linetable::{self, Locations, Position};
use heapspy_alloc::*;
use serde_json::Value;

struct FixtureCode {
    qualname: String,
    firstlineno: i32,
    code_bytes: u32,
    table: Vec<u8>,
    positions: Vec<Position>,
    lines: Vec<(u32, u32, Option<u32>)>,
}

fn opt(v: &Value) -> Option<u32> {
    v.as_u64().map(|n| n as u32)
}

fn load(minor: u8) -> (String, Vec<FixtureCode>) {
    let p = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures")
        .join(format!("linetable-3.{minor}.json"));
    let text = std::fs::read_to_string(&p).unwrap_or_else(|e| panic!("{}: {e}", p.display()));
    let doc: Value = serde_json::from_str(&text).unwrap();
    let version = doc["python"].as_str().unwrap().to_string();
    assert!(version.starts_with(&format!("3.{minor}.")), "{version}");
    let hex = |s: &str| -> Vec<u8> {
        (0..s.len())
            .step_by(2)
            .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap())
            .collect()
    };
    let codes = doc["codes"]
        .as_array()
        .unwrap()
        .iter()
        .map(|c| FixtureCode {
            qualname: c["qualname"].as_str().unwrap().into(),
            firstlineno: c["firstlineno"].as_i64().unwrap() as i32,
            code_bytes: c["code_bytes"].as_u64().unwrap() as u32,
            table: hex(c["linetable"].as_str().unwrap()),
            positions: c["positions"]
                .as_array()
                .unwrap()
                .iter()
                .map(|p| Position {
                    line: opt(&p[0]),
                    end_line: opt(&p[1]),
                    column: opt(&p[2]),
                    end_column: opt(&p[3]),
                })
                .collect(),
            lines: c["lines"]
                .as_array()
                .unwrap()
                .iter()
                .map(|r| {
                    (
                        r[0].as_u64().unwrap() as u32,
                        r[1].as_u64().unwrap() as u32,
                        opt(&r[2]),
                    )
                })
                .collect(),
        })
        .collect();
    (version, codes)
}

fn check_version(minor: u8) {
    let (version, codes) = load(minor);
    assert!(
        codes.len() >= 10,
        "{version}: only {} code objects",
        codes.len()
    );
    let mut forms = BTreeSet::new();
    for c in &codes {
        // The whole table decodes and covers co_code exactly.
        let entries: Vec<_> = Locations::new(&c.table, c.firstlineno)
            .map(|e| e.unwrap_or_else(|e| panic!("{version} {}: {e}", c.qualname)))
            .collect();
        assert_eq!(
            entries.last().map(|e| e.end),
            Some(c.code_bytes),
            "{version} {}",
            c.qualname
        );
        // Which entry forms this table uses (entry starts have bit 7 set).
        forms.extend(
            c.table
                .iter()
                .filter(|b| *b & 0x80 != 0)
                .map(|b| (b >> 3) & 15),
        );

        // co_positions(): one position per code unit.
        assert_eq!(c.positions.len() as u32 * 2, c.code_bytes);
        for (unit, want) in c.positions.iter().enumerate() {
            let off = unit as u32 * 2;
            let got = linetable::position_at(&c.table, c.firstlineno, off);
            assert_eq!(got, Some(*want), "{version} {} at byte {off}", c.qualname);
            // The odd byte of a code unit maps to the same position.
            assert_eq!(
                linetable::position_at(&c.table, c.firstlineno, off + 1),
                Some(*want)
            );
        }
        assert_eq!(
            linetable::position_at(&c.table, c.firstlineno, c.code_bytes),
            None
        );

        // co_lines(): byte ranges and their line.
        for &(start, end, line) in &c.lines {
            for off in (start..end).step_by(2) {
                assert_eq!(
                    linetable::line_at(&c.table, c.firstlineno, off),
                    line,
                    "{version} {} co_lines at byte {off}",
                    c.qualname
                );
            }
        }
    }
    // The source is written to need these forms: short (0-9), one-line
    // (10-12), long (14, multi-byte and negative deltas). 3.12 and later
    // also emit no-location entries (15) for artificial instructions.
    assert!(forms.iter().any(|f| *f <= 9), "{version}: no short form");
    assert!(
        forms.iter().any(|f| (10..=12).contains(f)),
        "{version}: no one-line form"
    );
    assert!(forms.contains(&14), "{version}: no long form");
    assert!(forms.contains(&15), "{version}: no no-location form");
}

#[test]
fn python_3_12() {
    check_version(12);
}

#[test]
fn python_3_13() {
    check_version(13);
}

#[test]
fn python_3_14() {
    check_version(14);
}

/// The same tables through the file format: write them as code entries,
/// sample every instruction, and read the lines back through `stack()`.
#[test]
fn through_profile() {
    for minor in [12u8, 13, 14] {
        let (_, codes) = load(minor);
        let mut b = ProfileBuilder::new();
        b.info_mut().python = PythonVersion::new(3, minor, 0);
        let fmt = LineTableFormat::for_python(b.info_mut().python).unwrap();
        assert_eq!(fmt, LineTableFormat::Locations311);
        let mut want = Vec::new();
        for (k, c) in codes.iter().enumerate() {
            let id = b.code(
                0x7f00_0000 + k as u64 * 0x1000,
                &c.qualname,
                "linetable_source.py",
                c.firstlineno,
                &c.table,
            );
            for (unit, pos) in c.positions.iter().enumerate() {
                b.sample(EventKind::LargeObject, 0x1000 + unit as u64, 1024)
                    .frame(id, unit as u32 * 2)
                    .frame_no_offset(id);
                want.push((c.qualname.clone(), pos.line, c.firstlineno));
            }
        }
        let p = b.build().unwrap();
        assert_eq!(p.sample_count() as usize, want.len());
        for (s, (q, line, first)) in p.samples().zip(&want) {
            let st: Vec<_> = p.stack(&s).collect();
            assert_eq!(st[0].qualname, Some(q.as_str()));
            assert_eq!(st[0].line, *line, "3.{minor} {q}");
            match line {
                Some(l) => assert_eq!(st[0].location(), format!("linetable_source.py:{l}")),
                None => assert_eq!(st[0].location(), "linetable_source.py:?"),
            }
            // No offset: co_firstlineno, as PyCode_Addr2Line does for -1.
            assert_eq!(st[1].line, Some(*first as u32));
        }
    }
}
